INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Voluntary B2G issuance, no B2B mandate — receiving-only obligation since 2020', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Cyprus has no confirmed timetable for a domestic B2B or B2G-issuance mandate as of this writing — confirm current status directly with the Ministry of Finance before building against it.', 'Cyprus completed a modest, receiving-only B2G e-invoicing rollout by April 2020 and has, since then, repeatedly discussed — but never enacted — a mandate for suppliers to actually issue e-invoices. A 1 January 2022 target for mandatory B2G issuance was proposed by the Ministry of Finance and quietly dropped; a similar push for 2024 met the same fate. No domestic B2B mandate has ever had a confirmed date. The one firm date on Cyprus''s horizon remains the EU-wide ViDA cross-border floor of 1 July 2030.', 'Where e-invoices are exchanged voluntarily, they follow the European Standard EN 16931, typically via the Peppol network or the government''s own portal — no separate Cypriot national format exists.', 'The only enforceable obligation in Cyprus today runs one direction: public sector bodies (central since 2019, all remaining public bodies since 2020) must be able to receive and process compliant e-invoices. Nothing requires a supplier to actually send one — B2G invoicing today happens on paper, by voluntary e-invoice, or by whatever bilateral arrangement a business and its government counterparty agree to.', 'With no domestic mandate — for B2G issuance or B2B — currently in force or scheduled, most businesses'' relevant work is limited to readiness rather than compliance: understanding that the receiving obligation exists on the government side, and preparing for the one date that is confirmed regardless of Cyprus''s own domestic decisions.', 'There is no domestic e-invoicing penalty regime in Cyprus today, for the simple reason that there is no domestic e-invoicing mandate for suppliers to fail to comply with. The only enforceable obligation sits with public bodies, not businesses.', 'Cyprus transposed EU Directive 2014/55/EU via Law 89(I)/2019, requiring central public sector bodies to receive EN 16931-compliant e-invoices from 18 April 2019, extended to all remaining public bodies from 18 April 2020. Issuance by suppliers has remained voluntary throughout. The Ministry of Finance discussed making B2G issuance mandatory from 1 January 2022, and again around 2024; neither target was ever enacted, and no domestic B2B mandate has a confirmed timetable. Separately, ViDA''s cross-border B2B e-invoicing and reporting mandate is confirmed EU law from 1 July 2030, regardless of any future Cypriot domestic decision.', '🇨🇾' FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Cyprus';
