INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Standard", "EN 16931, the European Standard on e-invoicing"], ["Legal basis", "Law 89(I)/2019, transposing EU Directive 2014/55/EU"], ["National format", "None — no separate Cypriot format exists alongside EN 16931"], ["B2B today", "No mandate; bilateral agreement between trading partners where used at all"]]', 'There''s no format decision to make here in the way there is in countries with their own national standard — EN 16931 via Peppol is simply the accepted approach wherever e-invoicing is used voluntarily.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["B2G receiving", "No registration needed — this is an obligation on public bodies, not suppliers"], ["Voluntary issuance", "Via a Peppol Access Point, or the government''s own portal"], ["Governing body", "Ministry of Finance"], ["B2B today", "No registration exists — nothing to register for"]]', 'Because there''s no issuance mandate, there''s genuinely no registration step for a typical business to complete — the obligation Cyprus has enacted so far applies entirely to the receiving side.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Where used", "Full EN 16931 core invoice model"], ["Mandatory fields", "None specified beyond the standard itself, since there''s no domestic mandate defining additional requirements"], ["Archiving", "Standard Cypriot record-keeping requirements apply regardless of format"]]', 'Without a domestic mandate specifying additional national fields (unlike, say, Poland''s KSeF or Italy''s SdI), a Cypriot e-invoice is simply a standard EN 16931 document — nothing extra to learn.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Model", "No clearance or real-time reporting regime of any kind"], ["B2G channel", "Peppol network or the government portal, for suppliers who choose to send electronically"], ["B2B channel", "Bilateral agreement, if used at all"], ["Real-time reporting", "None — Cyprus has no digital VAT reporting system"]]', 'This is about as light-touch a regulatory model as exists in this tracker — no clearance, no mandatory reporting, and only a receiving obligation on one side of one transaction type.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory today', '[["Central government bodies", "Must receive and process compliant e-invoices (since 2019)"], ["All other public bodies", "Must receive and process compliant e-invoices (since 2020)"], ["Suppliers to government", "No issuance obligation"], ["Private businesses (B2B/B2C)", "No obligation of any kind"]]', 'It''s worth being precise about this: Cyprus has never actually mandated that anyone send an e-invoice — only that certain public bodies be capable of accepting one if a supplier chooses to.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'A pattern of discussed-but-abandoned mandates', '[["2022 target", "Mandatory B2G issuance discussed by the Ministry of Finance, planned for 1 January 2022 — never enacted"], ["2024 target", "A similar push, tied to ERP implementation — also postponed indefinitely"], ["Current status", "No confirmed domestic timetable for either B2G issuance or B2B, as of this writing"], ["Firm floor regardless", "1 July 2030 — ViDA cross-border B2B, confirmed EU law"]]', 'This is the one entry on this page worth watching for a real signal — Cyprus has floated mandate dates twice before without following through, so the appropriate posture is to track official sources for a genuine legislative step, not just another discussion.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🤝 No penalty regime, because no mandate', NULL, NULL, 'There is no domestic penalty for failing to issue an e-invoice in Cyprus today, for the straightforward reason that no law requires it. The only enforceable obligation — receiving compliant invoices — sits with public bodies, not suppliers.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Twice proposed, twice dropped', NULL, NULL, 'Both the 2022 and 2024 targets for mandatory B2G issuance were genuine Ministry of Finance proposals, not rumours — but neither was followed through to actual legislation. Worth remembering if a future announcement surfaces: Cyprus has a track record of proposing dates it doesn''t keep.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇪🇺 The approaching EU floor', NULL, NULL, 'Regardless of whether Cyprus ever enacts its own domestic mandate, ViDA''s cross-border requirement is confirmed EU law from 1 July 2030 — every Cypriot business doing intra-EU B2B trade will need EN 16931-compliant e-invoicing and digital reporting for those transactions.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Understand what''s actually mandatory (very little)', 'Only public bodies'' receiving capability is required by law — there''s no issuance obligation for suppliers, and no B2B mandate of any kind today.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply Cypriot public bodies, consider voluntary e-invoicing', 'Sending structured e-invoices via Peppol may speed up processing even though it isn''t required — a low-cost way to get ahead of a future mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Don''t over-invest in tracking a specific domestic date', 'Cyprus has proposed mandate dates twice before (2022, 2024) without enacting either — treat any future announcement with appropriate caution until it''s genuinely confirmed in law.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 cross-border floor regardless', 'Every business doing intra-EU B2B trade needs EN 16931 e-invoicing and digital reporting capability from 1 July 2030 — this date is fixed by EU directive, not Cypriot discretion.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Cyprus';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch official sources, not advisor commentary, for the real signal', 'Given the pattern of discussed-but-abandoned targets, the Ministry of Finance''s own announcements are the only reliable indicator that something has actually changed.');
